const items = $input.all();

// Separamos: los que vienen del scraping tienen "formattedAddress", los de la hoja tienen "Direccion"
const nuevos = items.filter(item => item.json.formattedAddress);
const existentes = items.filter(item => item.json.Direccion).map(item => item.json.Direccion);

return nuevos.filter(item => !existentes.includes(item.json.formattedAddress));
